vector<int> topoSort(int n,
                     vector<vector<int>>& graph) {

    vector<int> indegree(n, 0);

    for (int u = 0; u < n; u++)
        for (int v : graph[u])
            indegree[v]++;

    queue<int> q;

    for (int i = 0; i < n; i++)
        if (indegree[i] == 0)
            q.push(i);

    vector<int> ans;

    while (!q.empty()) {

        int node = q.front();
        q.pop();

        ans.push_back(node);

        for (int next : graph[node]) {

            indegree[next]--;

            if (indegree[next] == 0)
                q.push(next);
        }
    }

    if (ans.size() != n)
        return {};

    return ans;
}

class DSU {

    vector<int> parent, size;

public:

    DSU(int n) {

        parent.resize(n);
        size.resize(n, 1);

        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {

        if (parent[x] == x)
            return x;

        return parent[x] = find(parent[x]);
    }

    void unite(int a, int b) {

        a = find(a);
        b = find(b);

        if (a == b)
            return;

        if (size[a] < size[b])
            swap(a, b);

        parent[b] = a;
        size[a] += size[b];
    }
};

vector<int> dijkstra(
    int src,
    vector<vector<pair<int,int>>>& graph) {

    int n = graph.size();

    vector<int> dist(n, INT_MAX);

    priority_queue<
        pair<int,int>,
        vector<pair<int,int>>,
        greater<pair<int,int>>
    > pq;

    dist[src] = 0;
    pq.push({0, src});

    while (!pq.empty()) {

        auto [d, node] = pq.top();
        pq.pop();

        if (d != dist[node])
            continue;

        for (auto [next, weight] : graph[node]) {

            if (dist[next] > d + weight) {

                dist[next] = d + weight;

                pq.push({dist[next], next});
            }
        }
    }

    return dist;
}

