public:

    Trie() {
        root = new TrieNode();
    }

    void insert(string word) {

        TrieNode* cur = root;

        for (char c : word) {

            int x = c - 'a';

            if (!cur->child[x])
                cur->child[x] = new TrieNode();

            cur = cur->child[x];
        }

        cur->end = true;
    }

    bool search(string word) {

        TrieNode* cur = root;

        for (char c : word) {

            int x = c - 'a';

            if (!cur->child[x])
                return false;

            cur = cur->child[x];
        }

        return cur->end;
    }

    bool startsWith(string prefix) {

        TrieNode* cur = root;

        for (char c : prefix) {

            int x = c - 'a';

            if (!cur->child[x])
                return false;

            cur = cur->child[x];
        }

        return true;
    }
};

