vector<int> primeFactorization(int n) {
    vector<int> factors;

    for (int p = 2; p * p <= n; p++) {
        while (n % p == 0) {
            factors.push_back(p);
            n /= p;
        }
    }

    if (n > 1)
        factors.push_back(n);

    return factors;
}

