vector<int> properFactors(int n) {
    vector<int> ans;

    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            if (i != n)
                ans.push_back(i);

            int other = n / i;

            if (other != i && other != n)
                ans.push_back(other);
        }
    }

    sort(ans.begin(), ans.end());
    return ans;
}

